import type { CipherSuites } from "../../../cipher/const";
import { binaryData } from "../../../imports/common";
import { FragmentedHandshake } from "../../../record/message/fragment";
import type {
  Extension,
  Handshake,
  Random,
  Version,
} from "../../../typings/domain";
import { ExtensionList, ProtocolVersion } from "../../binary";
import { HandshakeType } from "../../const";
import { DtlsRandom } from "../../random";

const { decode, encode, types } = binaryData;

// 7.4.1.3.  Server Hello

export class ServerHello implements Handshake {
  public serverVersion: Version;
  public random: Random;
  public sessionId: Buffer;
  public cipherSuite: CipherSuites;
  public compressionMethod: number;
  public extensions: Extension[];

  msgType: HandshakeType = HandshakeType.server_hello_2;
  messageSeq?: number;
  static readonly spec = {
    serverVersion: ProtocolVersion,
    random: DtlsRandom.spec,
    sessionId: types.buffer(types.uint8),
    cipherSuite: types.uint16be,
    compressionMethod: types.uint8,
  };

  constructor(
    serverVersion: Version,
    random: Random,
    sessionId: Buffer,
    cipherSuite: CipherSuites,
    compressionMethod: number,
    extensions: Extension[],
  ) {
    this.serverVersion = serverVersion;
    this.random = random;
    this.sessionId = sessionId;
    this.cipherSuite = cipherSuite;
    this.compressionMethod = compressionMethod;
    this.extensions = extensions;
  }

  static createEmpty() {
    return new ServerHello(
      undefined as any,
      undefined as any,
      undefined as any,
      undefined as any,
      undefined as any,
      undefined as any,
    );
  }

  static deSerialize(buf: Buffer) {
    const res = decode(buf, ServerHello.spec);
    const cls = new ServerHello(
      //@ts-expect-error
      ...Object.values(res),
    );
    const expect = cls.serialize();
    if (expect.length < buf.length) {
      return new ServerHello(
        //@ts-expect-error
        ...Object.values(
          decode(buf, { ...ServerHello.spec, extensions: ExtensionList }),
        ),
      );
    }
    return cls;
  }

  serialize() {
    return this.extensions === undefined
      ? encode(this, ServerHello.spec)
      : encode(this, {
          ...ServerHello.spec,
          extensions: ExtensionList,
        });
  }

  toFragment() {
    const body = this.serialize();
    return new FragmentedHandshake(
      this.msgType,
      body.length,
      this.messageSeq!,
      0,
      body.length,
      body,
    );
  }
}
